import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import {
  MapContainer,
  TileLayer,
  Polyline,
  Marker,
  Tooltip
} from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";

import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  LineElement,
  CategoryScale,
  LinearScale,
  PointElement,
  Legend
} from "chart.js";

ChartJS.register(LineElement, CategoryScale, LinearScale, PointElement, Legend);

function App() {
  const [data, setData] = useState([]);
  const [path, setPath] = useState([]);
  const [index, setIndex] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [shouldZoom, setShouldZoom] = useState(false);

  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");

  const mapRef = useRef();

  // 🧠 POINTS PER SECOND (FIXED)
  function computePointsPerSecond(data) {
    const bucket = {};

    data.forEach(p => {
      const ts = new Date(p.timestamp);
      const key = Math.floor(ts.getTime() / 1000);

      if (!bucket[key]) bucket[key] = 0;
      bucket[key]++;
    });

    return {
      labels: Object.keys(bucket),
      values: Object.values(bucket)
    };
  }

  // 🚀 FETCH DATA
 const fetchData = async () => {
  try {
    const res = await axios.get("http://localhost:3000/path", {
      params: {
        start: startTime,
        end: endTime
      }
    });

    const d = res.data;

    if (!d.length) {
      alert("No data found");
      return;
    }

    setData(d);
    setIndex(0);

    const coords = d.map(p => ({
      lat: p.lat,
      lng: p.lon,
      alt: p.alt || 0,
      voltage: p.voltage || 0,
      timestamp: p.timestamp
    }));

    setPath(coords);

    setShouldZoom(true);

  } catch (err) {
    console.error(err);
  }
};

  // 🔥 ZOOM AFTER RENDER (FIXED)
  useEffect(() => {
    if (!shouldZoom || !mapRef.current || path.length === 0) return;

    const first = path[0];

    console.log("🚀 Zooming to:", first);

    mapRef.current.flyTo(
      [first.lat, first.lng],
      19,
      { duration: 1.5 }
    );

    setShouldZoom(false);

  }, [shouldZoom, path]);

  // ▶ REAL-TIME PLAYBACK
useEffect(() => {
  if (!playing) return;
  if (index >= data.length - 1) return;

  const curr = new Date(data[index].timestamp);
  const next = new Date(data[index + 1].timestamp);

  const delay = Math.min(next - curr, 1000);

  const timer = setTimeout(() => {
    setIndex(prev => prev + 1);
  }, delay);

  return () => clearTimeout(timer);

}, [playing, data, index]);

  // 📍 FOLLOW DRONE
 useEffect(() => {
  if (!mapRef.current) return;
  if (!path[index]) return;

  mapRef.current.flyTo(
    [path[index].lat, path[index].lng],
    18,
    { duration: 0.5 }
  );

}, [index, path]);

  // 📊 ALT + BATTERY
  const chartData = {
    labels: path.slice(0, index).map((_, i) => i),
    datasets: [
      {
        label: "Altitude",
        data: path.slice(0, index).map(p => p.alt),
        borderColor: "cyan",
        tension: 0.3
      },
      {
        label: "Battery",
        data: path.slice(0, index).map(p => p.voltage),
        borderColor: "yellow",
        tension: 0.3
      }
    ]
  };

  // 📊 POINTS PER SECOND (SYNCED)
  const pps = computePointsPerSecond(data.slice(0, index));

  const ppsChart = {
    labels: pps.labels,
    datasets: [
      {
        label: "Points / Second",
        data: pps.values,
        borderColor: "lime",
        tension: 0.3
      }
    ]
  };

  const chartOptions = {
    plugins: {
      legend: {
        labels: { color: "white" }
      }
    },
    scales: {
      x: { ticks: { color: "white" } },
      y: { ticks: { color: "white" } }
    }
  };

  return (
    <div style={{ background: "black", color: "white", height: "100vh" }}>
      <h2>🚁 Drone Playback (Final)</h2>

      {/* ⏱ TIME FILTER */}
      <div>
        Start:
       <input
  type="datetime-local"
  onChange={e => {
    const utc = new Date(e.target.value).toISOString();
    setStartTime(utc);
  }}
/>
        End:
       <input
  type="datetime-local"
  onChange={e => {
    const utc = new Date(e.target.value).toISOString();
    setEndTime(utc);
  }}
/>
        <button onClick={fetchData}>Apply</button>
      </div>

      {/* ▶ CONTROLS */}
      <div>
        <button onClick={() => setPlaying(true)}>▶ Play</button>
        <button onClick={() => setPlaying(false)}>⏸ Pause</button>
      </div>

      {/* 🗺 MAP */}
      <MapContainer
        center={[12.97, 77.59]}
        zoom={13}
        style={{ height: "60vh" }}
        whenCreated={map => (mapRef.current = map)}
      >
        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

        <Polyline
          positions={path.slice(0, index).map(p => [p.lat, p.lng])}
          color="cyan"
          weight={4}
        />

        {/* 🔵 CURRENT POINT */}
        {path[index] && (
          <Marker
            position={[path[index].lat, path[index].lng]}
            icon={L.divIcon({
              html: `<div style="
                width:14px;height:14px;
                background:cyan;
                border-radius:50%;
                border:2px solid white;
                box-shadow:0 0 10px cyan;"></div>`
            })}
          >
            <Tooltip>
              Alt: {path[index].alt} m <br />
              Battery: {path[index].voltage} V
            </Tooltip>
          </Marker>
        )}
      </MapContainer>

      {/* 📊 ALT + BATTERY */}
      <div style={{ height: "20vh", background: "#111" }}>
        <Line data={chartData} options={chartOptions} />
      </div>

      {/* 📊 PPS */}
      <div style={{ height: "20vh", background: "#111" }}>
        <Line data={ppsChart} options={chartOptions} />
      </div>
    </div>
  );
}

export default App;
